import Mathlib.Data.Real.Basic
import Mathlib.Data.Nat.Basic
import Mathlib.Data.Fin.Basic
import Mathlib.Data.List.Basic
import Mathlib.Algebra.BigOperators.Basic
import Mathlib.Tactic
import Mathlib.Analysis.SpecialFunctions.Exp

open scoped BigOperators

namespace NormalizationKernels

abbrev BFloat16 := Fin 65536
abbrev FP32Word := Fin 4294967296

def BFloat16.fromBits (n : Nat) : BFloat16 := ⟨n % 65536, by omega⟩
def BFloat16.toBits (x : BFloat16) : Nat := x.1

def top16 (w : Nat) : Nat := (w / 65536) % 65536
def low16 (w : Nat) : Nat := w % 65536
def lsbOfTop16 (w : Nat) : Nat := top16 w % 2
def fp32ExponentBits (w : Nat) : Nat := (w / 8388608) % 256
def fp32FractionBits (w : Nat) : Nat := w % 8388608
def fp32IsNaNBits (w : Nat) : Prop := fp32ExponentBits w = 255 ∧ fp32FractionBits w ≠ 0
def fp32IsInfBits (w : Nat) : Prop := fp32ExponentBits w = 255 ∧ fp32FractionBits w = 0
def fp32ToBf16RNEBitsNat (w : Nat) : Nat := ((w + 32767 + lsbOfTop16 w) / 65536) % 65536
def fp32ToBf16QuietNaNBitsNat (w : Nat) : Nat :=
  if fp32IsNaNBits w then (top16 w + 64) % 65536 else fp32ToBf16RNEBitsNat w
def fp32ToBf16RNEBits (w : FP32Word) : BFloat16 := BFloat16.fromBits (fp32ToBf16RNEBitsNat w.1)
def fp32ToBf16QuietNaNBits (w : FP32Word) : BFloat16 := BFloat16.fromBits (fp32ToBf16QuietNaNBitsNat w.1)

theorem top16_lt (w : Nat) : top16 w < 65536 := by
  unfold top16
  exact Nat.mod_lt _ (by omega)

theorem low16_lt (w : Nat) : low16 w < 65536 := by
  unfold low16
  exact Nat.mod_lt _ (by omega)

theorem fp32ToBf16RNEBitsNat_lt (w : Nat) : fp32ToBf16RNEBitsNat w < 65536 := by
  unfold fp32ToBf16RNEBitsNat
  exact Nat.mod_lt _ (by omega)

theorem fp32ToBf16QuietNaNBitsNat_lt (w : Nat) : fp32ToBf16QuietNaNBitsNat w < 65536 := by
  unfold fp32ToBf16QuietNaNBitsNat
  split_ifs
  · exact Nat.mod_lt _ (by omega)
  · exact fp32ToBf16RNEBitsNat_lt w

theorem fp32ToBf16RNEBits_def (w : FP32Word) :
    fp32ToBf16RNEBits w = BFloat16.fromBits (fp32ToBf16RNEBitsNat w.1) := rfl

theorem fp32ToBf16QuietNaNBits_eq_nan_branch (w : FP32Word) (h : fp32IsNaNBits w.1) :
    fp32ToBf16QuietNaNBits w = BFloat16.fromBits ((top16 w.1 + 64) % 65536) := by
  unfold fp32ToBf16QuietNaNBits fp32ToBf16QuietNaNBitsNat
  simp [h]

theorem fp32ToBf16QuietNaNBits_eq_rne_branch (w : FP32Word) (h : ¬ fp32IsNaNBits w.1) :
    fp32ToBf16QuietNaNBits w = fp32ToBf16RNEBits w := by
  unfold fp32ToBf16QuietNaNBits fp32ToBf16QuietNaNBitsNat fp32ToBf16RNEBits
  simp [h]

def Vec (α : Type) (n : Nat) := Fin n → α

namespace Vec

def get (v : Vec α n) (i : Fin n) : α := v i
def set (v : Vec α n) (i : Fin n) (a : α) : Vec α n := fun j => if j = i then a else v j
def map (f : α → β) (v : Vec α n) : Vec β n := fun i => f (v i)
def zipWith (f : α → β → γ) (x : Vec α n) (y : Vec β n) : Vec γ n := fun i => f (x i) (y i)
def const (n : Nat) (a : α) : Vec α n := fun _ => a

def sum (v : Vec ℝ n) : ℝ := ∑ i : Fin n, v i
def sumAbs (v : Vec ℝ n) : ℝ := ∑ i : Fin n, |v i|
def sumSquares (v : Vec ℝ n) : ℝ := ∑ i : Fin n, v i * v i
def dot (x y : Vec ℝ n) : ℝ := ∑ i : Fin n, x i * y i

theorem sum_const (n : Nat) (a : ℝ) : sum (const n a) = n * a := by
  simp [sum, const]

theorem sumAbs_nonneg (v : Vec ℝ n) : 0 ≤ sumAbs v := by
  unfold sumAbs
  positivity

theorem sumSquares_nonneg (v : Vec ℝ n) : 0 ≤ sumSquares v := by
  unfold sumSquares
  positivity

end Vec

structure Memory (n : Nat) where
  read : Fin n → BFloat16

def addr (row col stride : Nat) : Nat := row * stride + col

structure StridedView (memSize rows cols stride : Nat) where
  h_cols : cols ≤ stride
  h_mem : rows * stride ≤ memSize

def indexFin {memSize rows cols stride : Nat} (v : StridedView memSize rows cols stride)
    (row : Fin rows) (col : Fin cols) : Fin memSize := by
  refine ⟨addr row.1 col.1 stride, ?_⟩
  have hcol : col.1 < stride := lt_of_lt_of_le col.2 v.h_cols
  have hstep : row.1 * stride + col.1 < row.1 * stride + stride := by
    exact Nat.add_lt_add_left hcol _
  have hrow : row.1 + 1 ≤ rows := Nat.succ_le_of_lt row.2
  have hblock : row.1 * stride + stride ≤ rows * stride := by
    calc
      row.1 * stride + stride = (row.1 + 1) * stride := by ring
      _ ≤ rows * stride := Nat.mul_le_mul_right _ hrow
  exact lt_of_lt_of_le hstep (le_trans hblock v.h_mem)

theorem addr_lt_memSize {memSize rows cols stride : Nat}
    (v : StridedView memSize rows cols stride)
    (row : Fin rows) (col : Fin cols) :
    addr row.1 col.1 stride < memSize := by
  exact (indexFin v row col).2

theorem addr_no_overflow_under_bound {memSize rows cols stride : Nat}
    (v : StridedView memSize rows cols stride)
    (row : Fin rows) (col : Fin cols) :
    addr row.1 col.1 stride ≤ rows * stride := by
  have hcol : col.1 ≤ stride := le_trans (Nat.le_of_lt col.2) v.h_cols
  calc
    addr row.1 col.1 stride = row.1 * stride + col.1 := rfl
    _ ≤ row.1 * stride + stride := Nat.add_le_add_left hcol _
    _ = (row.1 + 1) * stride := by ring
    _ ≤ rows * stride := Nat.mul_le_mul_right _ (Nat.succ_le_of_lt row.2)

def softmaxDenominatorExact (x : Vec ℝ n) : ℝ := ∑ i : Fin n, Real.exp (x i)

theorem softmaxDenominatorExact_pos (x : Vec ℝ n) : 0 < softmaxDenominatorExact x := by
  classical
  by_cases h : n = 0
  · subst h
    simp [softmaxDenominatorExact]
  · have : Nonempty (Fin n) := Fin.nonempty_iff_ne_zero.mpr h
    let i : Fin n := Classical.choice this
    have hterm : 0 < Real.exp (x i) := Real.exp_pos (x i)
    have hsum : 0 ≤ ∑ j : Fin n, Real.exp (x j) := by positivity
    unfold softmaxDenominatorExact
    exact lt_of_lt_of_le hterm hsum

def softmaxProbExact (x : Vec ℝ n) (i : Fin n) : ℝ :=
  Real.exp (x i) / softmaxDenominatorExact x

theorem softmaxProbExact_nonneg (x : Vec ℝ n) (i : Fin n) : 0 ≤ softmaxProbExact x i := by
  unfold softmaxProbExact
  positivity

def softmaxDenominatorRounded (x δ : Vec ℝ n) : ℝ :=
  softmaxDenominatorExact x + ∑ i : Fin n, δ i

theorem abs_sum_le_n_mul_eps (δ : Vec ℝ n) (ε : ℝ) (hε : 0 ≤ ε)
    (hδ : ∀ i : Fin n, |δ i| ≤ ε) :
    |∑ i : Fin n, δ i| ≤ n * ε := by
  have h1 : |∑ i : Fin n, δ i| ≤ ∑ i : Fin n, |δ i| := by
    simpa using Finset.abs_sum_le_sum_abs (s := Finset.univ) (f := fun i => δ i)
  have h2 : ∑ i : Fin n, |δ i| ≤ ∑ _i : Fin n, ε := by
    exact Finset.sum_le_sum fun i _ => hδ i
  have h3 : ∑ _i : Fin n, ε = n * ε := by simp
  nlinarith

theorem softmaxDenominatorRounded_error_bound
    (x δ : Vec ℝ n) (ε : ℝ) (hε : 0 ≤ ε)
    (hδ : ∀ i : Fin n, |δ i| ≤ ε) :
    |softmaxDenominatorRounded x δ - softmaxDenominatorExact x| ≤ n * ε := by
  unfold softmaxDenominatorRounded
  have hmain : |∑ i : Fin n, δ i| ≤ n * ε := abs_sum_le_n_mul_eps δ ε hε hδ
  simpa [sub_eq_add_neg, add_comm, add_left_comm, add_assoc] using hmain

def ulpBudget (n : Nat) (εulp : ℝ) : ℝ := n * εulp

theorem softmaxDenominatorRounded_error_bound_ulp
    (x δ : Vec ℝ n) (εulp : ℝ) (hε : 0 ≤ εulp)
    (hδ : ∀ i : Fin n, |δ i| ≤ εulp) :
    |softmaxDenominatorRounded x δ - softmaxDenominatorExact x| ≤ ulpBudget n εulp := by
  unfold ulpBudget
  exact softmaxDenominatorRounded_error_bound x δ εulp hε hδ

def rmsNormForwardSpec (input weight : Vec ℝ n) (eps : ℝ) : Vec ℝ n :=
  let meanSq := Vec.sumSquares input / n
  let inv := (meanSq + eps) ^ (-((1 : ℤ) : ℝ) / 2)
  fun i => input i * inv * weight i

def layerNormForwardSpec (input weight bias : Vec ℝ n) (eps : ℝ) : Vec ℝ n :=
  let mean := Vec.sum input / n
  let variance := Vec.sumSquares (fun i => input i - mean) / n
  let inv := (variance + eps) ^ (-((1 : ℤ) : ℝ) / 2)
  fun i => (input i - mean) * inv * weight i + bias i

def geluExactSpec (x : ℝ) : ℝ := x * (1 + Real.erf (x / Real.sqrt 2)) / 2

def softmaxForwardSpec (x : Vec ℝ n) : Vec ℝ n :=
  fun i => softmaxProbExact x i

def softmaxBackwardSpec (grad output : Vec ℝ n) : Vec ℝ n :=
  let dot := Vec.dot output grad
  fun i => output i * (grad i - dot)

theorem softmaxBackwardSpec_sum_zero
    (grad output : Vec ℝ n)
    (hprob : ∑ i : Fin n, output i = 1) :
    ∑ i : Fin n, softmaxBackwardSpec grad output i = 0 := by
  unfold softmaxBackwardSpec
  simp [Vec.dot, Finset.mul_sum, Finset.sum_sub_distrib, hprob]
  ring

def ExtractionRefines
    {σ τ : Type} (compile : σ → τ) (spec : σ → τ) : Prop :=
  ∀ x, compile x = spec x

def ZigRmsNormKernelSpec
    (input weight : Vec ℝ n) (eps : ℝ) : Vec ℝ n :=
  rmsNormForwardSpec input weight eps

def LeanSpecRefinesItself
    (input weight : Vec ℝ n) (eps : ℝ) :
    ExtractionRefines (fun _ : Unit => ZigRmsNormKernelSpec input weight eps)
      (fun _ : Unit => rmsNormForwardSpec input weight eps) := by
  intro _
  rfl

end NormalizationKernels
