const std = @import("std");
const math = std.math;

pub const BFloat16 = packed struct {
    bits: u16,

    pub inline fn fromBits(bits: u16) BFloat16 {
        return .{ .bits = bits };
    }

    pub inline fn toBits(self: BFloat16) u16 {
        return self.bits;
    }

    pub inline fn toFloat(self: BFloat16) f32 {
        const raw: u32 = @as(u32, self.bits) << 16;
        return @bitCast(raw);
    }

    pub inline fn fromFloat(x: f32) BFloat16 {
        const raw: u32 = @bitCast(x);
        const exp: u32 = (raw >> 23) & 0xFF;
        const frac: u32 = raw & 0x7FFFFF;
        if (exp == 0xFF) {
            if (frac != 0) {
                const top: u16 = @intCast(raw >> 16);
                return .{ .bits = top | 0x0040 };
            }
            return .{ .bits = @intCast(raw >> 16) };
        }
        const lsb: u32 = (raw >> 16) & 1;
        const rounding_bias: u32 = 0x7FFF + lsb;
        return .{ .bits = @intCast((raw + rounding_bias) >> 16) };
    }
};

fn VecF(comptime lanes: usize) type {
    return @Vector(lanes, f32);
}

fn splat(comptime lanes: usize, x: f32) VecF(lanes) {
    return @as(VecF(lanes), @splat(x));
}

fn loadBf16VectorAt(comptime lanes: usize, src: anytype, comptime start: usize) VecF(lanes) {
    const p: [*]const BFloat16 = @ptrCast(src);
    var out: VecF(lanes) = undefined;
    inline for (0..lanes) |i| {
        out[i] = p[start + i].toFloat();
    }
    return out;
}

fn storeBf16VectorAt(comptime lanes: usize, dst: anytype, comptime start: usize, value: VecF(lanes)) void {
    const p: [*]BFloat16 = @ptrCast(dst);
    inline for (0..lanes) |i| {
        p[start + i] = BFloat16.fromFloat(value[i]);
    }
}

fn horizontalSum(comptime lanes: usize, v: VecF(lanes)) f32 {
    return @reduce(.Add, v);
}

fn horizontalMax(comptime lanes: usize, v: VecF(lanes)) f32 {
    return @reduce(.Max, v);
}

fn expVec(comptime lanes: usize, v: VecF(lanes)) VecF(lanes) {
    var out: VecF(lanes) = undefined;
    inline for (0..lanes) |i| {
        out[i] = math.exp(v[i]);
    }
    return out;
}

fn tanhVec(comptime lanes: usize, v: VecF(lanes)) VecF(lanes) {
    var out: VecF(lanes) = undefined;
    inline for (0..lanes) |i| {
        out[i] = math.tanh(v[i]);
    }
    return out;
}

fn erfVec(comptime lanes: usize, v: VecF(lanes)) VecF(lanes) {
    var out: VecF(lanes) = undefined;
    inline for (0..lanes) |i| {
        out[i] = math.erf(v[i]);
    }
    return out;
}

fn zeroArray(comptime n: usize) [n]f32 {
    return [_]f32{0.0} ** n;
}

pub fn Kernel(
    comptime rows: usize,
    comptime cols: usize,
    comptime lanes: usize,
    comptime input_stride: usize,
    comptime output_stride: usize,
) type {
    comptime {
        if (cols == 0) @compileError("cols must be > 0");
        if (rows == 0) @compileError("rows must be > 0");
        if (lanes == 0) @compileError("lanes must be > 0");
        if (cols % lanes != 0) @compileError("cols must be divisible by lanes");
        if (input_stride < cols) @compileError("input_stride must be >= cols");
        if (output_stride < cols) @compileError("output_stride must be >= cols");
    }

    const chunk_count = cols / lanes;
    const VF = VecF(lanes);

    return struct {
        pub const Rows = rows;
        pub const Cols = cols;
        pub const Lanes = lanes;
        pub const InputStride = input_stride;
        pub const OutputStride = output_stride;

        pub fn rmsNormForward(
            input: *const [rows * input_stride]BFloat16,
            weight: *const [cols]BFloat16,
            output: *[rows * output_stride]BFloat16,
            eps: f32,
        ) void {
            @setFloatMode(.optimized);
            const n_inv: f32 = 1.0 / @as(f32, @floatFromInt(cols));
            inline for (0..rows) |row| {
                const in_base = row * input_stride;
                const out_base = row * output_stride;
                var sum_sq_vec: VF = splat(lanes, 0.0);
                inline for (0..chunk_count) |chunk| {
                    const start = in_base + chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, start);
                    sum_sq_vec += x * x;
                }
                const mean_sq = horizontalSum(lanes, sum_sq_vec) * n_inv;
                const inv = 1.0 / math.sqrt(mean_sq + eps);
                const inv_vec = splat(lanes, inv);
                inline for (0..chunk_count) |chunk| {
                    const x_start = in_base + chunk * lanes;
                    const w_start = chunk * lanes;
                    const y_start = out_base + chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, x_start);
                    const w = loadBf16VectorAt(lanes, weight, w_start);
                    storeBf16VectorAt(lanes, output, y_start, x * inv_vec * w);
                }
            }
        }

        pub fn rmsNormBackward(
            grad_output: *const [rows * output_stride]BFloat16,
            input: *const [rows * input_stride]BFloat16,
            weight: *const [cols]BFloat16,
            grad_input: *[rows * input_stride]BFloat16,
            grad_weight: *[cols]BFloat16,
            eps: f32,
        ) void {
            @setFloatMode(.optimized);
            var grad_weight_acc = zeroArray(cols);
            const n_inv: f32 = 1.0 / @as(f32, @floatFromInt(cols));
            inline for (0..rows) |row| {
                const in_base = row * input_stride;
                const go_base = row * output_stride;
                var sum_sq_vec: VF = splat(lanes, 0.0);
                inline for (0..chunk_count) |chunk| {
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk * lanes);
                    sum_sq_vec += x * x;
                }
                const mean_sq = horizontalSum(lanes, sum_sq_vec) * n_inv;
                const inv = 1.0 / math.sqrt(mean_sq + eps);
                const inv3 = inv * inv * inv;
                var sum_gwx_vec: VF = splat(lanes, 0.0);
                inline for (0..chunk_count) |chunk| {
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk * lanes);
                    const g = loadBf16VectorAt(lanes, grad_output, go_base + chunk * lanes);
                    const w = loadBf16VectorAt(lanes, weight, chunk * lanes);
                    sum_gwx_vec += g * w * x;
                }
                const sum_gwx = horizontalSum(lanes, sum_gwx_vec);
                const inv_vec = splat(lanes, inv);
                const corr_vec = splat(lanes, sum_gwx * inv3 * n_inv);
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk_offset);
                    const g = loadBf16VectorAt(lanes, grad_output, go_base + chunk_offset);
                    const w = loadBf16VectorAt(lanes, weight, chunk_offset);
                    const grad = w * inv_vec * g - x * corr_vec;
                    storeBf16VectorAt(lanes, grad_input, in_base + chunk_offset, grad);
                    const local = g * x * inv_vec;
                    inline for (0..lanes) |i| {
                        grad_weight_acc[chunk_offset + i] += local[i];
                    }
                }
            }
            inline for (0..cols) |i| {
                grad_weight[i] = BFloat16.fromFloat(grad_weight_acc[i]);
            }
        }

        pub fn layerNormForward(
            input: *const [rows * input_stride]BFloat16,
            weight: *const [cols]BFloat16,
            bias: *const [cols]BFloat16,
            output: *[rows * output_stride]BFloat16,
            eps: f32,
        ) void {
            @setFloatMode(.optimized);
            const n_inv: f32 = 1.0 / @as(f32, @floatFromInt(cols));
            inline for (0..rows) |row| {
                const in_base = row * input_stride;
                const out_base = row * output_stride;
                var sum_vec: VF = splat(lanes, 0.0);
                var sq_vec: VF = splat(lanes, 0.0);
                inline for (0..chunk_count) |chunk| {
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk * lanes);
                    sum_vec += x;
                    sq_vec += x * x;
                }
                const mean = horizontalSum(lanes, sum_vec) * n_inv;
                const mean_sq = horizontalSum(lanes, sq_vec) * n_inv;
                const variance = @max(0.0, mean_sq - mean * mean);
                const inv = 1.0 / math.sqrt(variance + eps);
                const mean_vec = splat(lanes, mean);
                const inv_vec = splat(lanes, inv);
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk_offset);
                    const w = loadBf16VectorAt(lanes, weight, chunk_offset);
                    const b = loadBf16VectorAt(lanes, bias, chunk_offset);
                    const y = (x - mean_vec) * inv_vec * w + b;
                    storeBf16VectorAt(lanes, output, out_base + chunk_offset, y);
                }
            }
        }

        pub fn layerNormBackward(
            grad_output: *const [rows * output_stride]BFloat16,
            input: *const [rows * input_stride]BFloat16,
            weight: *const [cols]BFloat16,
            grad_input: *[rows * input_stride]BFloat16,
            grad_weight: *[cols]BFloat16,
            grad_bias: *[cols]BFloat16,
            eps: f32,
        ) void {
            @setFloatMode(.optimized);
            var grad_weight_acc = zeroArray(cols);
            var grad_bias_acc = zeroArray(cols);
            const n_inv: f32 = 1.0 / @as(f32, @floatFromInt(cols));
            inline for (0..rows) |row| {
                const in_base = row * input_stride;
                const go_base = row * output_stride;
                var sum_vec: VF = splat(lanes, 0.0);
                var sq_vec: VF = splat(lanes, 0.0);
                inline for (0..chunk_count) |chunk| {
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk * lanes);
                    sum_vec += x;
                    sq_vec += x * x;
                }
                const mean = horizontalSum(lanes, sum_vec) * n_inv;
                const mean_sq = horizontalSum(lanes, sq_vec) * n_inv;
                const variance = @max(0.0, mean_sq - mean * mean);
                const inv = 1.0 / math.sqrt(variance + eps);
                const inv3 = inv * inv * inv;
                const mean_vec = splat(lanes, mean);
                const inv_vec = splat(lanes, inv);

                var sum_grad_vec: VF = splat(lanes, 0.0);
                var sum_grad_centered_vec: VF = splat(lanes, 0.0);
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk_offset);
                    const g = loadBf16VectorAt(lanes, grad_output, go_base + chunk_offset);
                    const w = loadBf16VectorAt(lanes, weight, chunk_offset);
                    const centered = x - mean_vec;
                    const gw = g * w;
                    sum_grad_vec += gw;
                    sum_grad_centered_vec += gw * centered;
                }

                const sum_grad = horizontalSum(lanes, sum_grad_vec);
                const sum_grad_centered = horizontalSum(lanes, sum_grad_centered_vec);
                const term2_vec = splat(lanes, sum_grad * inv * n_inv);
                const term3_coeff_vec = splat(lanes, sum_grad_centered * inv3 * n_inv);

                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk_offset);
                    const g = loadBf16VectorAt(lanes, grad_output, go_base + chunk_offset);
                    const w = loadBf16VectorAt(lanes, weight, chunk_offset);
                    const centered = x - mean_vec;
                    const term1 = g * w * inv_vec;
                    const term3 = centered * term3_coeff_vec;
                    const grad = term1 - term2_vec - term3;
                    storeBf16VectorAt(lanes, grad_input, in_base + chunk_offset, grad);

                    const dw = g * centered * inv_vec;
                    inline for (0..lanes) |i| {
                        grad_weight_acc[chunk_offset + i] += dw[i];
                        grad_bias_acc[chunk_offset + i] += g[i];
                    }
                }
            }
            inline for (0..cols) |i| {
                grad_weight[i] = BFloat16.fromFloat(grad_weight_acc[i]);
                grad_bias[i] = BFloat16.fromFloat(grad_bias_acc[i]);
            }
        }

        pub fn geluForwardApproximate(
            input: *const [rows * input_stride]BFloat16,
            output: *[rows * output_stride]BFloat16,
        ) void {
            @setFloatMode(.optimized);
            const sqrt_2_over_pi: f32 = 0.7978845608028653559;
            const coeff: f32 = 0.0447149984538555145;
            inline for (0..rows) |row| {
                const in_base = row * input_stride;
                const out_base = row * output_stride;
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk_offset);
                    const x3 = x * x * x;
                    const inner = splat(lanes, sqrt_2_over_pi) * (x + splat(lanes, coeff) * x3);
                    const y = splat(lanes, 0.5) * x * (splat(lanes, 1.0) + tanhVec(lanes, inner));
                    storeBf16VectorAt(lanes, output, out_base + chunk_offset, y);
                }
            }
        }

        pub fn geluBackwardApproximate(
            grad_output: *const [rows * output_stride]BFloat16,
            input: *const [rows * input_stride]BFloat16,
            grad_input: *[rows * input_stride]BFloat16,
        ) void {
            @setFloatMode(.optimized);
            const sqrt_2_over_pi: f32 = 0.7978845608028653559;
            const coeff: f32 = 0.0447149984538555145;
            const coeff3: f32 = 0.1341449953616565435;
            inline for (0..rows) |row| {
                const in_base = row * input_stride;
                const go_base = row * output_stride;
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk_offset);
                    const g = loadBf16VectorAt(lanes, grad_output, go_base + chunk_offset);
                    const x2 = x * x;
                    const x3 = x2 * x;
                    const tanh_arg = splat(lanes, sqrt_2_over_pi) * (x + splat(lanes, coeff) * x3);
                    const tanh_val = tanhVec(lanes, tanh_arg);
                    const sech_sq = splat(lanes, 1.0) - tanh_val * tanh_val;
                    const inner_deriv = splat(lanes, sqrt_2_over_pi) * (splat(lanes, 1.0) + splat(lanes, coeff3) * x2);
                    const deriv = splat(lanes, 0.5) * (splat(lanes, 1.0) + tanh_val) + splat(lanes, 0.5) * x * sech_sq * inner_deriv;
                    storeBf16VectorAt(lanes, grad_input, in_base + chunk_offset, g * deriv);
                }
            }
        }

        pub fn geluForwardExact(
            input: *const [rows * input_stride]BFloat16,
            output: *[rows * output_stride]BFloat16,
        ) void {
            @setFloatMode(.optimized);
            const sqrt2: f32 = 1.4142135623730950488;
            inline for (0..rows) |row| {
                const in_base = row * input_stride;
                const out_base = row * output_stride;
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk_offset);
                    const y = splat(lanes, 0.5) * x * (splat(lanes, 1.0) + erfVec(lanes, x / splat(lanes, sqrt2)));
                    storeBf16VectorAt(lanes, output, out_base + chunk_offset, y);
                }
            }
        }

        pub fn geluBackwardExact(
            grad_output: *const [rows * output_stride]BFloat16,
            input: *const [rows * input_stride]BFloat16,
            grad_input: *[rows * input_stride]BFloat16,
        ) void {
            @setFloatMode(.optimized);
            const sqrt2: f32 = 1.4142135623730950488;
            const inv_sqrt_2pi: f32 = 0.3989422804014326779;
            inline for (0..rows) |row| {
                const in_base = row * input_stride;
                const go_base = row * output_stride;
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk_offset);
                    const g = loadBf16VectorAt(lanes, grad_output, go_base + chunk_offset);
                    const cdf = splat(lanes, 0.5) * (splat(lanes, 1.0) + erfVec(lanes, x / splat(lanes, sqrt2)));
                    const pdf = expVec(lanes, splat(lanes, -0.5) * x * x) * splat(lanes, inv_sqrt_2pi);
                    storeBf16VectorAt(lanes, grad_input, in_base + chunk_offset, g * (cdf + x * pdf));
                }
            }
        }

        pub fn softmaxForward(
            input: *const [rows * input_stride]BFloat16,
            output: *[rows * output_stride]BFloat16,
        ) void {
            @setFloatMode(.optimized);
            inline for (0..rows) |row| {
                const in_base = row * input_stride;
                const out_base = row * output_stride;
                var max_vec = loadBf16VectorAt(lanes, input, in_base);
                inline for (1..chunk_count) |chunk| {
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk * lanes);
                    max_vec = @max(max_vec, x);
                }
                const row_max = horizontalMax(lanes, max_vec);

                var tmp: [cols]f32 = undefined;
                var sum_vec: VF = splat(lanes, 0.0);
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const x = loadBf16VectorAt(lanes, input, in_base + chunk_offset);
                    const shifted = x - splat(lanes, row_max);
                    const ex = expVec(lanes, shifted);
                    inline for (0..lanes) |i| {
                        tmp[chunk_offset + i] = ex[i];
                    }
                    sum_vec += ex;
                }
                const inv_sum = 1.0 / horizontalSum(lanes, sum_vec);
                const inv_sum_vec = splat(lanes, inv_sum);
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    var ex: VF = undefined;
                    inline for (0..lanes) |i| {
                        ex[i] = tmp[chunk_offset + i];
                    }
                    storeBf16VectorAt(lanes, output, out_base + chunk_offset, ex * inv_sum_vec);
                }
            }
        }

        pub fn softmaxBackward(
            grad_output: *const [rows * output_stride]BFloat16,
            output: *const [rows * output_stride]BFloat16,
            grad_input: *[rows * input_stride]BFloat16,
        ) void {
            @setFloatMode(.optimized);
            inline for (0..rows) |row| {
                const go_base = row * output_stride;
                const out_base = row * output_stride;
                const gi_base = row * input_stride;
                var dot_vec: VF = splat(lanes, 0.0);
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const s = loadBf16VectorAt(lanes, output, out_base + chunk_offset);
                    const g = loadBf16VectorAt(lanes, grad_output, go_base + chunk_offset);
                    dot_vec += s * g;
                }
                const dot = horizontalSum(lanes, dot_vec);
                const dot_vec_broadcast = splat(lanes, dot);
                inline for (0..chunk_count) |chunk| {
                    const chunk_offset = chunk * lanes;
                    const s = loadBf16VectorAt(lanes, output, out_base + chunk_offset);
                    const g = loadBf16VectorAt(lanes, grad_output, go_base + chunk_offset);
                    storeBf16VectorAt(lanes, grad_input, gi_base + chunk_offset, s * (g - dot_vec_broadcast));
                }
            }
        }
    };
}

